import unittest
from solution import nearest_bundle


class NearestBundleTests(unittest.TestCase):
    def test_nearest_profile_marker_and_direct_child_rule(self):
        entries = {
            "/work/quartz.mod",
            "/work/app/module.qproj",
            "/work/app/src/deeper/ignored.qproj",
        }
        snapshot = set(entries)
        self.assertEqual(
            nearest_bundle("/work/app/src/file.txt", "quartz", entries),
            "/work/app",
        )
        self.assertEqual(entries, snapshot)

    def test_each_profile_and_root_marker(self):
        self.assertEqual(
            nearest_bundle("/a/b/doc", "ember", {"/a/ember.lock"}), "/a"
        )
        self.assertEqual(
            nearest_bundle("/a/b/doc", "orbit", {"/a/b/project.orb"}), "/a/b"
        )
        self.assertEqual(
            nearest_bundle("/doc", "orbit", {"/orbit.map"}), "/"
        )

    def test_anchor_fallback_and_default_directory(self):
        entries = {"/a/.anchor", "/a/b/c/.anchor"}
        self.assertEqual(
            nearest_bundle("/a/b/c/doc.txt", "ember", entries), "/a/b/c"
        )
        self.assertEqual(
            nearest_bundle("/a/b/doc.txt", "ember", set()), "/a/b"
        )

    def test_profile_marker_takes_precedence_over_anchor(self):
        entries = {"/a/b/.anchor", "/a/ember.lock"}
        self.assertEqual(
            nearest_bundle("/a/b/doc.txt", "ember", entries), "/a"
        )

    def test_type_validation(self):
        calls = [
            (1, "quartz", set()),
            ("/a/file", 1, set()),
            ("/a/file", "quartz", []),
            ("/a/file", "quartz", {1}),
        ]
        for args in calls:
            with self.subTest(args=args):
                with self.assertRaises(TypeError):
                    nearest_bundle(*args)

    def test_value_validation(self):
        bad_documents = ["relative/file", "/", "/a/", "/a//file", "/a/./file", "/a/../file"]
        for path in bad_documents:
            with self.subTest(path=path):
                with self.assertRaises(ValueError):
                    nearest_bundle(path, "quartz", set())
        with self.assertRaises(ValueError):
            nearest_bundle("/a/file", "unknown", set())
        for entry in ("relative", "/a//b", "/a/./b", "/a/../b", "/a/"):
            with self.subTest(entry=entry):
                with self.assertRaises(ValueError):
                    nearest_bundle("/a/file", "orbit", {entry})


if __name__ == "__main__":
    unittest.main()

